70: async function onAttemptFailure({error, attemptNumber, retriesConsumed, startTime, options}) {
71: 	const normalizedError = error instanceof Error
72: 		? error
73: 		: new TypeError(`Non-error was thrown: "${error}". You should only throw errors.`);
74: 
75: 	if (normalizedError instanceof AbortError) {
76: 		throw normalizedError.originalError;
77: 	}
78: 
79: 	const retriesLeft = Number.isFinite(options.retries)
80: 		? Math.max(0, options.retries - retriesConsumed)
81: 		: options.retries;
82: 
83: 	const maxRetryTime = options.maxRetryTime ?? Number.POSITIVE_INFINITY;
84: 	const delayTime = calculateDelay(retriesConsumed, options);
85: 	const remainingTimeBeforeCallbacks = calculateRemainingTime(startTime, maxRetryTime);
86: 
87: 	if (remainingTimeBeforeCallbacks <= 0) {
88: 		const context = Object.freeze({
89: 			error: normalizedError,
90: 			attemptNumber,
91: 			retriesLeft,
92: 			retriesConsumed,
93: 			retryDelay: 0,
94: 		});
95: 
96: 		await options.onFailedAttempt(context);
97: 
98: 		throw normalizedError;
99: 	}
100: 
101: 	const consumeRetryContext = Object.freeze({
102: 		error: normalizedError,
103: 		attemptNumber,
104: 		retriesLeft,
105: 		retriesConsumed,
106: 		retryDelay: retriesLeft > 0 ? delayTime : 0,
107: 	});
108: 
109: 	const consumeRetry = await options.shouldConsumeRetry(consumeRetryContext);
110: 	const effectiveDelay = consumeRetry && retriesLeft > 0 ? delayTime : 0;
111: 	const context = Object.freeze({
112: 		error: normalizedError,
113: 		attemptNumber,
114: 		retriesLeft,
115: 		retriesConsumed,
116: 		retryDelay: effectiveDelay,
117: 	});
118: 
119: 	await options.onFailedAttempt(context);
120: 
121: 	if (calculateRemainingTime(startTime, maxRetryTime) <= 0) {
122: 		throw normalizedError;
123: 	}
124: 
125: 	const remainingTime = calculateRemainingTime(startTime, maxRetryTime);
126: 
127: 	if (remainingTime <= 0 || retriesLeft <= 0) {
128: 		throw normalizedError;
129: 	}
130: 
131: 	if (normalizedError instanceof TypeError && !isNetworkError(normalizedError)) {
132: 		throw normalizedError;
133: 	}
134: 
135: 	if (!await options.shouldRetry(context)) {
136: 		throw normalizedError;
137: 	}
138: 
139: 	if (!consumeRetry) {
140: 		options.signal?.throwIfAborted();
141: 		return false;
142: 	}
143: 
144: 	const finalDelay = Math.min(effectiveDelay, remainingTime);
145: 
146: 	options.signal?.throwIfAborted();
147: 
148: 	if (finalDelay > 0) {
149: 		await new Promise((resolve, reject) => {
150: 			const onAbort = () => {
151: 				clearTimeout(timeoutToken);
152: 				options.signal?.removeEventListener('abort', onAbort);
153: 				reject(options.signal.reason);
154: 			};
155: 
156: 			const timeoutToken = setTimeout(() => {
157: 				options.signal?.removeEventListener('abort', onAbort);
158: 				resolve();
159: 			}, finalDelay);
160: 
161: 			if (options.unref) {
162: 				timeoutToken.unref?.();
163: 			}
164: 
165: 			options.signal?.addEventListener('abort', onAbort, {once: true});
166: 		});
167: 	}
168: 
169: 	options.signal?.throwIfAborted();
170: 
171: 	return true;
172: }
