174: export default async function pRetry(input, options = {}) {
175: 	options = {...options};
176: 
177: 	validateRetries(options.retries);
178: 
179: 	if (Object.hasOwn(options, 'forever')) {
180: 		throw new Error('The `forever` option is no longer supported. For many use-cases, you can set `retries: Infinity` instead.');
181: 	}
182: 
183: 	options.retries ??= 10;
184: 	options.factor ??= 2;
185: 	options.minTimeout ??= 1000;
186: 	options.maxTimeout ??= Number.POSITIVE_INFINITY;
187: 	options.maxRetryTime ??= Number.POSITIVE_INFINITY;
188: 	options.randomize ??= false;
189: 	options.onFailedAttempt ??= () => {};
190: 	options.shouldRetry ??= () => true;
191: 	options.shouldConsumeRetry ??= () => true;
192: 
193: 	// Validate numeric options and normalize edge cases
194: 	validateNumberOption('factor', options.factor, {min: 0, allowInfinity: false});
195: 	validateNumberOption('minTimeout', options.minTimeout, {min: 0, allowInfinity: false});
196: 	validateNumberOption('maxTimeout', options.maxTimeout, {min: 0, allowInfinity: true});
197: 	validateNumberOption('maxRetryTime', options.maxRetryTime, {min: 0, allowInfinity: true});
198: 
199: 	// Treat non-positive factor as 1 to avoid zero backoff or negative behavior
200: 	if (!(options.factor > 0)) {
201: 		options.factor = 1;
202: 	}
203: 
204: 	options.signal?.throwIfAborted();
205: 
206: 	let attemptNumber = 0;
207: 	let retriesConsumed = 0;
208: 	const startTime = performance.now();
209: 
210: 	while (Number.isFinite(options.retries) ? retriesConsumed <= options.retries : true) {
211: 		attemptNumber++;
212: 
213: 		try {
214: 			options.signal?.throwIfAborted();
215: 
216: 			const result = await input(attemptNumber);
217: 
218: 			options.signal?.throwIfAborted();
219: 
220: 			return result;
221: 		} catch (error) {
222: 			if (await onAttemptFailure({
223: 				error,
224: 				attemptNumber,
225: 				retriesConsumed,
226: 				startTime,
227: 				options,
228: 			})) {
229: 				retriesConsumed++;
230: 			}
231: 		}
232: 	}
233: 
234: 	// Should not reach here, but in case it does, throw an error
235: 	throw new Error('Retry attempts exhausted without throwing an error.');
236: }
